<?php require ( getenv( 'WPENV' ) ?: '/tmp/wpenv' ) . '/site/wp-load.php'; global $wpdb; mt_srand(9);
$lt=flxi_table('log'); $mt=flxi_table('mail'); $wpdb->query("DELETE FROM $lt"); $wpdb->query("DELETE FROM $mt");
$names=['Ayşe Yılmaz','Mehmet Demir','Elif Arslan','Can Şahin','Zeynep Kaya','Burak Çelik','Merve Öztürk','Emre Koç','Selin Aydın','Kerem Polat'];
$tpl=[['flx-certificates/certificate','flx-certificates','Fidan bağış sertifikanız hazır 🌱'],['flx-forms/form-received','flx-forms','Mesajınızı aldık (takip kodu {k})'],['flx-donate/receipt-uploaded','flx-donate','Havale dekontu yüklendi'],['wp/new-user','wordpress','Örnek Vakfı hesabınız oluşturuldu'],['flx-donate/recurring-started','flx-donate','Aylık bağışınız başladı']];
$now=current_time('timestamp'); $rows=[];
for($d=29;$d>=0;$d--) for($i=0,$n=mt_rand(3,9);$i<$n;$i++){ $t=$tpl[mt_rand(0,4)]; $nm=$names[array_rand($names)]; $em=strtolower(remove_accents(str_replace(' ','.',$nm))).'@example.org';
 $ch=mt_rand(1,6)==1?'whatsapp':'email'; $st=mt_rand(1,25)==1?'failed':'sent'; $ts=date('Y-m-d H:i:s',$now-$d*86400-mt_rand(0,40000)); if($ts>current_time('mysql')) continue;
 $rows[]=(['created_at'=>$ts,'channel'=>$ch,'template'=>$t[0],'source'=>$t[1],'recipient'=>$ch=='email'?$em:'+90 532 '.mt_rand(100,999).' '.mt_rand(10,99).' '.mt_rand(10,99),'subject'=>str_replace('{k}',strtoupper(wp_generate_password(6,false)),$t[2]),'status'=>$st,'error'=>$st=='failed'?'SMTP: 550 mailbox unavailable':null,'mailer'=>$ch=='email'?'smtp':'evolution','sender'=>'bilgi@example.org','body'=>'<p>Merhaba '.$nm.',</p><p>'.$t[2].'</p>']); }
usort($rows,fn($a,$b)=>strcmp($a['created_at'],$b['created_at'])); foreach($rows as $r) $wpdb->insert($lt,$r);
$in=[['Okul kampanyası hakkında','Merhaba, okulumuzda 11 Kasım için fidan kampanyası düzenlemek istiyoruz. Nasıl ilerleyebiliriz?'],['Kurumsal bağış teklifi','Şirketimiz adına 500 fidanlık bir bağış planlıyoruz, teklif alabilir miyiz?'],['Sertifikadaki isim','Sertifikamda soyadım yanlış yazılmış, düzeltebilir misiniz?'],['Gönüllülük','Hafta sonları gönüllü olarak destek vermek istiyorum.'],['Basın: Hatıra Ormanı','Hatıra Ormanı projesi hakkında haber yapmak istiyoruz, görüşebilir miyiz?'],['Re: Fidan dikimi','Fotoğrafları paylaştığınız için çok teşekkürler!'],['Dekont','Ekte havale dekontumu gönderiyorum.']];
foreach($in as $i=>[$s,$b]){ $nm=$names[$i]; $em=strtolower(remove_accents(str_replace(' ','.',$nm))).'@example.org'; $ts=date('Y-m-d H:i:s',$now-$i*14000-600);
 $wpdb->insert($mt,['folder'=>'inbox','source'=>'imap','uid'=>100+$i,'message_id'=>'<m'.$i.'@example.org>','thread_key'=>md5($s),'from_email'=>$em,'from_name'=>$nm,'to_list'=>'bilgi@example.org','subject'=>$s,'snippet'=>mb_substr($b,0,120),'body_text'=>$b."\n\nSevgiler,\n".$nm,'attachments'=>$i==6?wp_json_encode([['name'=>'dekont.pdf','size'=>84000,'mime'=>'application/pdf']]):'[]','size'=>2000,'mail_date'=>$ts,'is_read'=>$i>2?1:0,'is_starred'=>$i==1?1:0,'replied'=>$i==5?1:0,'created_at'=>$ts]); }
echo "log ".$wpdb->get_var("SELECT COUNT(*) FROM $lt")." mail ".$wpdb->get_var("SELECT COUNT(*) FROM $mt")."\n";
